def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # If no opponents are alive, conserve budget.
    if not alive_opps:
        return max(0.0, min(float(my_status.get('budget', 0.0)), DAILY_SALARY * 0.35))

    # Read opponents' yesterday bids (immediate reaction only).
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    my_budget = float(my_status.get('budget', 0.0))
    my_hp = float(my_status.get('hp', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    # Estimate how many full requirements are available.
    # (Use only for sizing our bid, not for indexing.)
    max_full_units = supply / float(WATER_REQ) if WATER_REQ > 0 else 0.0

    # Base target bid level.
    # Aggressive if any opponent bid was very high yesterday.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # Thresholds tuned to DAILY_SALARY scale.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # They likely expect scarcity; bid enough to compete but not max out.
            if my_hp <= 2 or my_no_water_days >= 2:
                target = DAILY_SALARY * 0.75
            else:
                target = DAILY_SALARY * 0.55
        elif highest_prev_bid >= DAILY_SALARY * 0.55:
            # Moderate pressure: slight raise over low baseline.
            if my_hp <= 2 or my_no_water_days >= 2:
                target = DAILY_SALARY * 0.65
            else:
                target = DAILY_SALARY * 0.45
        else:
            # Low yesterday bids: we can undercut.
            if my_hp <= 2 or my_no_water_days >= 2:
                target = DAILY_SALARY * 0.55
            else:
                target = DAILY_SALARY * 0.35
    else:
        # No trace info: conservative baseline.
        if my_hp <= 2 or my_no_water_days >= 2:
            target = DAILY_SALARY * 0.6
        else:
            target = DAILY_SALARY * 0.4

    # Adjust for supply: when supply is closer to MIN_SUPPLY, scarcity is higher.
    if supply <= float(MIN_SUPPLY) + 0.5:
        target *= 1.08
    elif supply >= float(MAX_SUPPLY) - 0.5:
        target *= 0.92

    # If we are likely to be in danger, increase bid.
    if my_hp <= 1:
        target *= 1.25

    # Ensure we don't bid more than we can afford.
    bid = min(my_budget, target)

    # Keep bid within [0, budget].
    if bid < 0.0:
        bid = 0.0
    return float(bid)
